export type TableAssetName = keyof typeof tableAssetUrls;

export const tableAssetManifest = manifest;

/** UV offset/repeat for one card face in the shared atlas. */
export function cardAtlasCell(col: number, row: number) {
  const { cols, rows } = manifest.card.atlas;
  return {
    repeat: [1 / cols, 1 / rows] as const,
    offset: [col / cols, 1 - (row + 1) / rows] as const,
  };
}
